effect.shader:
const float PI = 3.14159265;
mat3 mrotX(float a){ float s=sin(a),c=cos(a); return mat3(1.0,0.0,0.0, 0.0,c,-s, 0.0,s,c); }
mat3 mrotY(float a){ float s=sin(a),c=cos(a); return mat3(c,0.0,s, 0.0,1.0,0.0, -s,0.0,c); }
mat3 mrotZ(float a){ float s=sin(a),c=cos(a); return mat3(c,-s,0.0, s,c,0.0, 0.0,0.0,1.0); }
void main(){
    vec2 ndc=acScreenNorm*2.0-1.0; float asp=acScreenSize.x/acScreenSize.y; ndc.x*=asp;
    mat3 R=mrotX(radians(spinX))*mrotY(radians(spinY));
    vec3 ro=R*vec3(0.0,0.0,-3.2);
    vec3 rd=R*normalize(vec3(ndc,2.6));
    vec3 m=1.0/rd; vec3 b=abs(m);
    vec3 t1=-m-b; vec3 t2=-m+b;
    float tN=max(max(t1.x,t1.y),t1.z);
    float tF=min(min(t2.x,t2.y),t2.z);
    if(tN>tF||tF<0.0){gl_FragColor=vec4(0.0);return;}
    vec3 hit=ro+rd*tN;
    vec3 an=abs(hit);
    vec2 uv; vec3 nrm;
    if(an.x>=an.y&&an.x>=an.z){ uv=hit.zy*sign(hit.x); nrm=vec3(sign(hit.x),0.0,0.0); }
    else if(an.y>=an.z){ uv=hit.xz*sign(hit.y); nrm=vec3(0.0,sign(hit.y),0.0); }
    else { uv=hit.xy*sign(-hit.z); nrm=vec3(0.0,0.0,sign(hit.z)); }
    uv=uv*0.5+0.5;
    vec4 col=texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
    float diff=clamp(dot(R*nrm, normalize(vec3(-0.5,0.6,-0.6))),0.0,1.0);
    col.rgb *= mix(1.0, 0.35+0.75*diff, light);
    gl_FragColor=col;
}
